    im=ax.imshow(field.T,extent=[0,1,0,1],origin='lower',vmin=-m,vmax=m,cmap='RdBu_r');ax.set(title=title,xlabel='Model coordinate x',ylabel='Model coordinate y');fig.colorbar(im,ax=ax,shrink=.8,label='Signed S')
